import csv, time
from operator import add
from itertools import islice
def v_orig(path):
    with open(path, newline="") as f:
        r=csv.reader(f); h=next(r); t=[0.0]*len(h)
        for row in r:
            for i,v in enumerate(row):
                try: t[i]+=float(v)
                except ValueError: pass
    return dict(zip(h,t))
def _slow(t,row):
    for i,v in enumerate(row):
        try: t[i]+=float(v)
        except ValueError: pass
def v_mapadd(path):
    with open(path, newline="") as f:
        r=csv.reader(f); h=next(r); n=len(h); t=[0.0]*n
        for row in r:
            if len(row)==n:
                try:
                    t=list(map(add,t,map(float,row))); continue
                except ValueError: pass
            _slow(t,row)
    return dict(zip(h,t))
def v_cols(path):
    # transpose all-numeric rows in big chunks, float+sum per column via map
    with open(path, newline="") as f:
        r=csv.reader(f); h=next(r); n=len(h); t=[0.0]*n
        while True:
            b=list(islice(r,65536))
            if not b: break
            good=[]; ap=good.append
            for row in b:
                if len(row)==n: ap(row)
                else: _slow(t,row)
            for i,col in enumerate(zip(*good)):
                try: t[i]+=sum(map(float,col))
                except ValueError:
                    for v in col:
                        try: t[i]+=float(v)
                        except ValueError: pass
    return dict(zip(h,t))
def v_split(path):
    with open(path, newline="") as f:
        r=csv.reader(f); h=next(r); n=len(h); t=[0.0]*n
        while True:
            b=list(islice(r,65536))
            if not b: break
            good=[]; ap=good.append
            for row in b:
                if len(row)==n: ap(row)
                else: _slow(t,row)
            for i,col in enumerate(zip(*good)):
                try: t[i]+=sum(map(float,col))
                except ValueError:
                    s=0.0
                    for v in col:
                        try: s+=float(v)
                        except ValueError: pass
                    t[i]+=s
    return dict(zip(h,t))
if __name__=='__main__':
    ref=v_orig('big.csv')
    for fn in (v_orig,v_mapadd,v_cols,v_split):
        ts=[]
        for _ in range(3):
            t0=time.perf_counter(); res=fn('big.csv'); ts.append(time.perf_counter()-t0)
        print(fn.__name__, f'{min(ts):.3f}s', res==ref)
